@RequestMapping(method = RequestMethod.DELETE)
    public String delete(@RequestParam("saleProductCode") String saleProductCode,
                         @RequestParam("version") Integer version,
                         @RequestParam("saleTemplateCode") String saleTemplateCode,
                         @RequestParam(value = "saleComponentCodes", required = false) String saleComponentCodes) {
        return execute(() -> {
            List<String> saleTemplateCodeList = new ArrayList<>(1);
            saleTemplateCodeList.add(saleTemplateCode);

            List<SaleProductComponentDO> list = saleProductComponentMapper.selectBySaleProductTemplateVersion(saleProductCode, version, saleTemplateCodeList);
            if (list.isEmpty()) {
                throw new RuntimeException("数据不存在");
            }
            List<Long> deleteList = new ArrayList<>();
            if (saleComponentCodes != null) {
                String[] codes = saleComponentCodes.split(",");
                list.forEach(item -> {
                    for (String code : codes) {
                        if (code.equalsIgnoreCase(item.getSaleComponentCode())) {
                            deleteList.add(item.getId());
                        }
                    }
                });
            } else {
                list.forEach(item -> {
                    deleteList.add(item.getId());
                });
            }

            if (deleteList.isEmpty()) {
                return Response.ofFailed(ErrorEnum.SYS_INNER_DB_ERROR.getErrorCode(), "删除数据不能为空");
            }

            transactionRepository.execute(() -> {
                deleteList.forEach(id -> {
                    int size = saleProductComponentMapper.deleteByPrimaryKey(id);
                    if (size != 1) {
                        throw new RuntimeException("删除失败,id:" + id);
                    }
                });
            });
            return Response.ofSuccess();
        });
    }

